    private void btnCadastrarActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnCadastrarActionPerformed
        String nome = txtNome.getText().trim().toUpperCase();
    String cpf = txtCPF.getText().replaceAll("\\D", "");           // só números
    String telefone = txtTelefone.getText().replaceAll("\\D", ""); // só números
    String email = txtEmail.getText().trim().toUpperCase();
    String endereco = txtEndereco.getText().trim().toUpperCase();
    boolean ativo = ckbAtivo.isSelected();

    if (nome.isEmpty() || cpf.isEmpty()) {
        JOptionPane.showMessageDialog(this, "Preencha o nome e o CPF!",
                "Atenção", JOptionPane.WARNING_MESSAGE);
        return;
    }

    String sqlInsert = """
            INSERT INTO cliente
            (nome, cpf, telefone, email, endereco, ativo)
            VALUES (?, ?, ?, ?, ?, ?)
            """;

    try (Connection conex = conexao.conectar()) {

        if (conex == null) {
            JOptionPane.showMessageDialog(this,
                    "Não foi possível conectar ao banco de dados!",
                    "Erro", JOptionPane.ERROR_MESSAGE);
            return;
        }

        try (PreparedStatement stmt = conex.prepareStatement(sqlInsert)) {
            stmt.setString(1, nome);
            stmt.setString(2, cpf);
            stmt.setString(3, telefone);
            stmt.setString(4, email);
            stmt.setString(5, endereco);
            stmt.setBoolean(6, ativo);

            int linhas = stmt.executeUpdate();
            if (linhas > 0) {
                JOptionPane.showMessageDialog(this, "Cadastro do cliente realizado com sucesso!");
                limparCampos();
            }
        }

    } catch (SQLException erro) {
        JOptionPane.showMessageDialog(this,
                "Não foi possível cadastrar o cliente! - Erro: " + erro.getMessage());
    }
    }//GEN-LAST:event_btnCadastrarActionPerformed

    private void btnLimparActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLimparActionPerformed
         limparCampos();
}

private void limparCampos() {
    txtId.setText("");
    txtNome.setText("");
    txtCPF.setText("");
    txtTelefone.setText("");
    txtEmail.setText("");
    txtEndereco.setText("");
    ckbAtivo.setSelected(true);
    txtNome.requestFocus();
    }//GEN-LAST:event_btnLimparActionPerformed

